import type { StructureResolver } from 'sanity/structure';
import { HiDocumentText, HiScale } from 'react-icons/hi2';
import { MdMenu, MdOutlineHome } from 'react-icons/md';
import { IoSettingsSharp } from 'react-icons/io5';

/**
 * The Studio sidebar, arranged the way the client thinks about the site
 * rather than by document type (generated by pws-scaffolder from the sitemap):
 *
 *   Website pages (menu order) · Legal pages
 *   ─────  the site's content: services, posts, events…
 *   ─────  Forms
 *   ─────  Menus · Site settings
 *
 * Pages, legal pages, menus and settings exist once each and are listed by
 * name; the client edits them but can't create or delete them (FIXED_TYPES).
 */

/** Documents the site is built around: edited, never created or deleted by the client */
export const FIXED_TYPES = ['page', 'legalPage', 'navigation', 'siteSettings'];

const PAGES: { id: string; title: string }[] = [
  { id: 'page-home', title: 'Home' },
  { id: 'page-about', title: 'About' },
  { id: 'page-contact', title: 'Contact' },
  { id: 'page-donate', title: 'Donate' },
];

const LEGAL: { id: string; title: string }[] = [
  { id: 'legal-privacy-policy', title: 'Privacy Policy' },
  { id: 'legal-terms-and-conditions', title: 'Terms & Conditions' },
  { id: 'legal-accessibility', title: 'Accessibility Statement' },
];

const MENUS: { id: string; title: string }[] = [
  { id: 'nav-main', title: 'Main menu (top of every page)' },
  { id: 'nav-legal', title: 'Legal links (bottom bar)' },
];

/** The site's other content, in the order the sidebar lists it */
const CONTENT: string[] = ['footerColumns'];
const HAS_FORMS = false;

/** Arranged above, or kept out of the sidebar (the Publish site log) */
const ARRANGED = [...FIXED_TYPES, ...CONTENT, 'dynamicForm', 'sitePublish'];

export const structure: StructureResolver = (S) => {
  const named = (list: { id: string; title: string }[], schemaType: string, icon: typeof HiDocumentText) =>
    list.map(({ id, title }) =>
      S.listItem()
        .id(id)
        .title(title)
        .icon(id === 'page-home' ? MdOutlineHome : icon)
        .child(S.document().schemaType(schemaType).documentId(id).title(title))
    );
  const pageIds = PAGES.map((p) => p.id);

  return S.list()
    .title('Website')
    .items([
      S.listItem()
        .title('Website pages')
        .icon(HiDocumentText)
        .child(
          S.list()
            .title('Website pages')
            .items([
              ...named(PAGES, 'page', HiDocumentText),
              S.divider(),
              // Pages the web team adds later, until they're arranged above
              S.listItem()
                .title('Other pages')
                .icon(HiDocumentText)
                .child(
                  S.documentList()
                    .title('Other pages')
                    .schemaType('page')
                    .filter('_type == "page" && !(_id in $ids) && !(_id in path("drafts.**"))')
                    .params({ ids: pageIds })
                ),
            ])
        ),
      ...(LEGAL.length
        ? [S.listItem().title('Legal pages').icon(HiScale).child(S.list().title('Legal pages').items(named(LEGAL, 'legalPage', HiScale)))]
        : []),
      S.divider(),
      ...CONTENT.map((type) => S.documentTypeListItem(type)),
      ...S.documentTypeListItems().filter((item) => !ARRANGED.includes(item.getId() ?? '')),
      ...(HAS_FORMS ? [S.divider(), S.documentTypeListItem('dynamicForm').title('Forms')] : []),
      S.divider(),
      ...(MENUS.length ? [S.listItem().title('Menus').icon(MdMenu).child(S.list().title('Menus').items(named(MENUS, 'navigation', MdMenu)))] : []),
      S.listItem()
        .id('siteSettings')
        .title('Site settings')
        .icon(IoSettingsSharp)
        .child(S.document().schemaType('siteSettings').documentId('siteSettings').title('Site settings')),
    ]);
};
